"""Mutalia-e-Quran XII PDF12: p.9 — verse 4:11 (begun on p.8); 4:12 begins here and is recorded on p.10. Run: python class12_quran_page012.py"""
from class12_quran_common import BOOK, Builder, rec, V


def p12():
    b = Builder()
    V(b, 4, 11, 'اللہ تمھیں تمھاری اولاد (کی وراثت) کے بارے میں وصیت فرماتا ہے بیٹے کے لیے دو بیٹیوں کے برابر حصہ ہے پھر اگر صرف دو (یا دو) سے زائد بیٹیاں ہوں تو جو (ترکہ میت نے) چھوڑا اُن کے لیے اُس کا دو تہائی ہے اور اگر ایک ہی بیٹی ہو تو اُس کے لیے نصف (ترکہ) ہے اور (میت کے) ماں باپ دونوں میں سے ہر ایک کے لیے چھٹا حصہ ہے اُس میں سے جو (میت نے) چھوڑا اگر اُس (میت) کی اولاد ہے اور اگر اُس کی کوئی اولاد نہیں ہے اور اُس کے ماں باپ (ہی) اُس کے وارث ہوئے تو اُس کی ماں کا تیسرا حصہ ہے پھر اگر اُس کے کئی بھائی ہیں تو اُس کی ماں کا چھٹا حصہ ہے (یہ تقسیم ہو گی) اس وصیت پر عمل کرنے کے بعد جو (مرنے والا) کر گیا یا (اُس کے) قرض ادا کرنے کے بعد تمھارے باپ اور تمھارے بیٹے تم نہیں جانتے کہ اُن میں سے کون تمھیں نفع پہنچانے کے اعتبار سے زیادہ قریب ہے یہ حصے اللہ کی طرف سے مقرر ہیں بے شک اللہ خوب جاننے والا بڑی حکمت والا ہے۔',
      'الله تاسو ته ستاسو د اولاد (د میراث) په اړه وصیت کوي: زوی لپاره د دوو لوڼو په اندازه برخه ده؛ بیا که یوازې دوه (یا) له دوو زیاتې لوڼې وي، نو د هغه (ترکې) دوه پر درېیمه برخه یې ده چې (مړي) پرېښې؛ او که یوازې یوه لور وي، نو نیمه (ترکه) یې ده؛ او د (مړي) مور او پلار هر یوه لپاره د هغه څه شپږمه برخه ده چې (مړي) پرې ایښي، که د هغه (مړي) اولاد وي؛ او که یې هېڅ اولاد نه وي او یوازې مور او پلار یې وارثان شي، نو مور یې درېیمه برخه لري؛ بیا که یې څو وروڼه وي، نو مور یې شپږمه برخه لري — (دا وېش به) د هغه وصیت پر عمل له کولو وروسته (وي) چې (مړي) کړی، یا د (هغه) پور له ورکولو وروسته. ستاسو پلرونه او ستاسو زامن — تاسو نه پوهېږئ چې په هغو کې څوک تاسو ته د ګټې رسولو له پلوه نږدې دی؛ دا برخې د الله له خوا ټاکل شوې دي؛ بې‌شکه الله ښه پوه، ډېر حکمتناک دی.')
    BOOK.save(12, [(1, rec(b, 1, 12, 12))], issues=[{'id': 'mq12-pdf012', 'unit': 1, 'printedPage': 9,
               'description': 'Verse 4:11 (begun on p.8) is recorded here. Verse 4:12 runs from mid-p.9 to the top of p.10 and is recorded with p.10.'}])


if __name__ == '__main__':
    p12()
